  'nova-seq': () => form('Nova sequência', '<label class="cmp">Nome<input name="n" required value="Pós-visita técnica"></label><p class="vaz">Começa com 3 passos (D+1 WhatsApp, D+3 ligação, D+7 e-mail) que você edita depois.</p>', 'Criar', (f) => { db.sequencias.push({ id: uid(), nome: f.get('n'), passos: [[1, 'WhatsApp'], [3, 'Ligação'], [7, 'E-mail']], ativos: 0, ligada: false }); }),
  'novo-perdido': () => form('Negócio perdido', `<div class="duas"><label class="cmp">Cliente<input name="c" required maxlength="80"></label><label class="cmp">WhatsApp<input name="t" inputmode="tel"></label></div><div class="duas"><label class="cmp">Motivo<select name="m" data-livre>${['Preço', 'Financiamento negado', 'Comprou do concorrente', 'Sem resposta', 'Desistiu'].map((m) => `<option>${m}</option>`).join('')}</select></label><label class="cmp">Valor (R$)<input name="v" inputmode="decimal"></label></div><div class="duas"><label class="cmp">Vendedor<select name="d" data-livre="vend">${db.vend.map((v) => `<option value="${v.id}">${h(v.nome)}</option>`).join('')}</select></label><label class="cmp">Há quantos dias<input name="q" type="number" min="0" value="0"></label></div>`, 'Registrar', (f) => { db.perdidos.push({ id: uid(), cliente: String(f.get('c')).trim(), motivo: String(f.get('m')).trim() || 'Sem motivo', valor: nv(f.get('v')) || 0, dono: f.get('d'), dia: -(Number(f.get('q')) || 0), contato: String(f.get('c')).trim(), tel: fone(f.get('t')), origem: 'Manual', kwp: 0 }); nota('Registrado nos motivos de perda.'); }),
