  editar: (dd) => { const d = deal(dd.id); fechaJanelas(); form(`Editar · ${h(d.cliente)}`, `<div class="duas"><label class="cmp">Cliente<input name="c" required value="${h(d.cliente)}"></label><label class="cmp">Contato<input name="p" required value="${h(d.contato)}"></label></div><div class="duas"><label class="cmp">WhatsApp<input name="t" inputmode="tel" value="${h(d.tel)}"></label><label class="cmp">Origem<input name="o" value="${h(d.origem)}"></label></div><div class="duas"><label class="cmp">Valor (R$)<input name="v" inputmode="decimal" required value="${d.valor}"></label><label class="cmp">Potência (kWp)<input name="k" type="number" min="0" step="0.1" value="${d.kwp}"></label></div><label class="cmp">Endereço (para a rota das visitas)<input name="e" maxlength="120" value="${h(d.end || '')}"></label><label class="cmp">Previsão de fechamento (dias a partir de hoje)<input name="pv" type="number" min="0" value="${d.prev ?? 30}"></label>`, 'Salvar', (f) => { const v = nv(f.get('v')); if (!(v > 0)) { nota('Informe o valor.'); return false; } const dup = duplicado(f.get('c'), f.get('t'), d); if (dup && !confirm(`${dup.cliente} já está no funil. Salvar assim mesmo?`)) return false; if (v !== d.valor) d.hist.unshift({ d: 0, t: `Valor mudou de ${R$(d.valor)} para ${R$(v)}` }); Object.assign(d, { cliente: String(f.get('c')).trim(), contato: String(f.get('p')).trim(), tel: fone(f.get('t')), origem: String(f.get('o')).trim() || d.origem, valor: v, kwp: Number(f.get('k')) || 0, prev: Math.max(0, Math.round(Number(f.get('pv')) || 0)), end: String(f.get('e') || '').trim() }); nota('Negócio salvo.'); }); },
